(7496157, 1194155, 114225, '<td valign="top">Did you applie a huge amount of noise reduction? The sky looks unnatural.</td>', 'Did you applie a huge amount of noise reduction? The sky looks unnatural.', '2017-02-01 11:15:40.000000', NULL, 1),
(7496158, 1194330, 114225, '<td valign="top">Nicely shot image. I like the bit of mystique.</td>', 'Nicely shot image. I like the bit of mystique.', '2017-02-01 11:18:08.000000', NULL, 1),
(7496160, 1194169, 114225, '<td valign="top">Excellently composed photo. I don''t like the processing at all. The shadows are too bight and the clarity seems too high.</td>', 'Excellently composed photo. I don''t like the processing at all. The shadows are too bight and the clarity seems too high.', '2017-02-01 11:19:50.000000', NULL, 1),
(7496161, 1194397, 114225, '<td valign="top">Really good detail and I love the light used.</td>', 'Really good detail and I love the light used.', '2017-02-01 11:20:11.000000', NULL, 1),
(7496163, 1194545, 114225, '<td valign="top">Why is that other car in the frame? That is distracting? Just moving yoruself a bit to the left could have solved that.</td>', 'Why is that other car in the frame? That is distracting? Just moving yoruself a bit to the left could have solved that.', '2017-02-01 11:21:13.000000', NULL, 1),
(7496164, 1194678, 114225, '<td valign="top">Oh, that is cool. All in camera with a strobe, I assume. That makes getting the face this perfect hard. Well done.</td>', 'Oh, that is cool. All in camera with a strobe, I assume. That makes getting the face this perfect hard. Well done.', '2017-02-01 11:21:55.000000', NULL, 1),
(7496165, 1194463, 114225, '<td valign="top">This photo has a lot of power. I really like that.</td>', 'This photo has a lot of power. I really like that.', '2017-02-01 11:22:10.000000', NULL, 1),
(7496166, 1194361, 114225, '<td valign="top">Oh my. I haven''t seen light like that around here in a while. That is just stunning.</td>', 'Oh my. I haven''t seen light like that around here in a while. That is just stunning.', '2017-02-01 11:22:47.000000', NULL, 1),
(7496167, 1193879, 114225, '<td valign="top">Excellent macro. Good colors without over saturating. Great detail. Perfect composition.</td>', 'Excellent macro. Good colors without over saturating. Great detail. Perfect composition.', '2017-02-01 11:23:09.000000', NULL, 1),
(7496168, 1194220, 114225, '<td valign="top">Very cool image. I might prefer it a little brighter, but just a bit.</td>', 'Very cool image. I might prefer it a little brighter, but just a bit.', '2017-02-01 11:23:32.000000', NULL, 1),
(7496169, 1194593, 114225, '<td valign="top">I like this. Seems like a story in the making. I might have chosen to crop the right side tighter, so the tracks go to the corner of the frame.</td>', 'I like this. Seems like a story in the making. I might have chosen to crop the right side tighter, so the tracks go to the corner of the frame.', '2017-02-01 11:26:48.000000', NULL, 1),
(7496171, 1194085, 114225, '<td valign="top">I find myself gazing longingly into this.</td>', 'I find myself gazing longingly into this.', '2017-02-01 11:27:56.000000', NULL, 1),
(7496173, 1193531, 114225, '<td valign="top">There is a ton of noise here. Cleaning that up would be nice. I would also choose to crop out the land in the foreground.</td>', 'There is a ton of noise here. Cleaning that up would be nice. I would also choose to crop out the land in the foreground.', '2017-02-01 11:29:48.000000', NULL, 1),
(7496174, 1194491, 114225, '<td valign="top">Overall, this is good. Not great, but good. If I was in this position, I think I would try to move slightly to the left, and compose such that most of the left side of the image isn''t there. Keep the eyes focused on the road on main city.</td>', 'Overall, this is good. Not great, but good. If I was in this position, I think I would try to move slightly to the left, and compose such that most of the left side of the image isn''t there. Keep the eyes focused on the road on main city.', '2017-02-01 11:31:33.000000', NULL, 1),
